const base = $('Normalizar Entrada').first().json;
const user = $('Buscar Usuario').first().json || {};

// Verificamos si existe (ahora que buscar usuario funciona, esto será true)
const exists = !!(user.row_number || user.telegram_user);

// Limpiamos el valor de 'activo' (detecta "si")
const activoDb = String(user.activo || '').trim().toLowerCase();
const active = ['si', 'true', '1', 'activo'].includes(activoDb);

return [{
  json: {
    ...base,
    nombre: user.nombre || base.first_name,
    rol: String(user.rol || 'USUARIO').toUpperCase(),
    activo: activoDb,
    user_exists: exists,
    user_active: exists && active,
    user_route: (exists && active) ? 'ACTIVE' : 'BLOCKED',
  }
}];

const ctx = $('Validar Usuario').first().json; const reason = ctx.user_exists ? 'Tu usuario esta registrado pero no se encuentra activo.' : 'No encontre tu usuario en la hoja USUARIOS.'; return [{ json: { ...ctx, reply_text: `Hola ${ctx.first_name}.

${reason}

Pidele al administrador que revise tu acceso antes de continuar.` } }];

const ctx = $('Validar Usuario').first().json;
const logs = $input.all().map(item => item.json).filter(log => log.timestamp);

// Ordenar logs por fecha descendente (el más nuevo primero)
const sortedLogs = logs.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

const text = String(ctx.message_text || '').trim();
const normalized = text.toUpperCase();
const forceMenuValues = ['/START', '/MENU', 'MENU', 'INICIO'];

let route_state = 'SHOW_MENU';

if (!text || forceMenuValues.includes(normalized)) {
  route_state = 'SHOW_MENU';
} else {
  // Buscar si hay un proceso pendiente
  const pending = sortedLogs.find(log => 
    ['CREAR_TIPO', 'CREAR_PRIORIDAD', 'CREAR_DESCRIPCION', 'CREAR_CONFIRMACION', 'CONSULTAR_TICKET'].includes(log.pantalla) && 
    String(log.resultado).toUpperCase() === 'PENDIENTE'
  );

  if (pending) {
    route_state = pending.pantalla;
  } else {
    route_state = 'MENU_PRINCIPAL';
  }
}

// Recuperar datos del Wizard para cuando el usuario está en pasos intermedios
const lastType = sortedLogs.find(l => l.pantalla === 'CREAR_TIPO' && !['PENDIENTE', 'INVALIDO', 'CANCELADO'].includes(String(l.resultado).toUpperCase()));
const lastPriority = sortedLogs.find(l => l.pantalla === 'CREAR_PRIORIDAD' && !['PENDIENTE', 'INVALIDO', 'CANCELADO'].includes(String(l.resultado).toUpperCase()));
const lastDescription = sortedLogs.find(l => l.pantalla === 'CREAR_DESCRIPCION' && !['PENDIENTE', 'INVALIDO', 'CANCELADO'].includes(String(l.resultado).toUpperCase()));

return [{
  json: {
    ...ctx,
    route_state,
    menu_option: text,
    wizard_type: lastType?.resultado || '',
    wizard_priority: lastPriority?.resultado || '',
    wizard_description: lastDescription?.resultado || '',
    can_report: ['ADMIN', 'SOPORTE'].includes(ctx.rol) ? 'ALLOW' : 'DENY'
  }
}];

const ctx = $('Resolver Estado').first().json; return [{ json: { ...ctx, reply_text: `Escribe el ID del ticket que quieres consultar.

Ejemplo: HD-20260428-101530

9. Cancelar` } }];

